def handle(app, svc):
    resp = svc.apply(app)
    if isinstance(resp, dict) and resp.get("api_version") == 2 and "result" in resp:
        result = resp["result"]
        outcome = result.get("outcome")
        limit = int(result.get("credit_limit") or 0)
    else:
        outcome = resp.get("decision")
        limit = int(resp.get("limit") or 0)

    # Network rule: self_employed with requested_limit > 6000 -> manual review (unless declined)
    if (app.get("employment") == "self_employed"
            and int(app.get("requested_limit") or 0) > 6000
            and outcome != "declined" and outcome != "decline"):
        return {"action": "queue_review", "limit": 0}

    if outcome in ("approve", "approved"):
        return {"action": "issue", "limit": limit}
    if outcome in ("decline", "declined"):
        return {"action": "decline", "limit": 0}
    # refer / manual_review
    return {"action": "queue_review", "limit": 0}

